import { useMemo, useState } from 'react';
import {
  JxChip,
  JxBadge,
  JxProgressCircle,
  JxPagination,
  JxEmptyState,
  JxButton,
} from '@jinx-ui/react';

type ProjectStatus = 'active' | 'paused' | 'over-quota' | 'completed';

interface Project {
  id: string;
  name: string;
  status: ProjectStatus;
  quotaPercent: number;
}

const STATUS_META: Record<
  ProjectStatus,
  { label: string; badgeVariant: 'success' | 'warning' | 'danger' | 'neutral' }
> = {
  active: { label: 'Активен', badgeVariant: 'success' },
  paused: { label: 'На паузе', badgeVariant: 'neutral' },
  'over-quota': { label: 'Превышена квота', badgeVariant: 'danger' },
  completed: { label: 'Завершён', badgeVariant: 'warning' },
};

const ALL_STATUSES = Object.keys(STATUS_META) as ProjectStatus[];

const PROJECTS: Project[] = [
  { id: 'p1', name: 'Atlas Billing', status: 'active', quotaPercent: 62 },
  { id: 'p2', name: 'Nova Reporting', status: 'over-quota', quotaPercent: 118 },
  { id: 'p3', name: 'Solaris CRM', status: 'paused', quotaPercent: 34 },
  { id: 'p4', name: 'Lumen Analytics', status: 'active', quotaPercent: 47 },
  { id: 'p5', name: 'Vector Search', status: 'completed', quotaPercent: 100 },
  { id: 'p6', name: 'Orbit Notify', status: 'active', quotaPercent: 81 },
  { id: 'p7', name: 'Echo Support', status: 'paused', quotaPercent: 12 },
  { id: 'p8', name: 'Pulse Metrics', status: 'over-quota', quotaPercent: 143 },
  { id: 'p9', name: 'Drift Storage', status: 'active', quotaPercent: 55 },
  { id: 'p10', name: 'Beacon Auth', status: 'completed', quotaPercent: 100 },
  { id: 'p11', name: 'Cascade ETL', status: 'paused', quotaPercent: 8 },
  { id: 'p12', name: 'Halo Search', status: 'active', quotaPercent: 73 },
];

const PAGE_SIZE = 5;

export default function ProjectQuotaPanel() {
  const [activeStatuses, setActiveStatuses] = useState<Set<ProjectStatus>>(
    new Set(ALL_STATUSES),
  );
  const [page, setPage] = useState(1);

  const toggleStatus = (status: ProjectStatus) => {
    setActiveStatuses((prev) => {
      const next = new Set(prev);
      if (next.has(status)) {
        next.delete(status);
      } else {
        next.add(status);
      }
      return next;
    });
    setPage(1);
  };

  const resetFilters = () => {
    setActiveStatuses(new Set(ALL_STATUSES));
    setPage(1);
  };

  const filteredProjects = useMemo(
    () => PROJECTS.filter((project) => activeStatuses.has(project.status)),
    [activeStatuses],
  );

  const pageCount = Math.max(1, Math.ceil(filteredProjects.length / PAGE_SIZE));
  const currentPage = Math.min(page, pageCount);
  const pageStart = (currentPage - 1) * PAGE_SIZE;
  const pageProjects = filteredProjects.slice(pageStart, pageStart + PAGE_SIZE);

  return (
    <div
      className="jx-stack"
      style={{ gap: 'var(--jx-space-6)', maxWidth: 640 }}
    >
      <div
        className="jx-stack"
        style={{ gap: 'var(--jx-space-2)' }}
      >
        <span
          className="jx-text-caption"
          style={{ color: 'var(--jx-color-text-secondary)' }}
        >
          Фильтр по статусу
        </span>
        <div
          className="jx-flex"
          style={{ gap: 'var(--jx-space-2)', flexWrap: 'wrap' }}
        >
          {ALL_STATUSES.map((status) => (
            <JxChip
              key={status}
              selected={activeStatuses.has(status)}
              onClick={() => toggleStatus(status)}
              onRemove={
                activeStatuses.has(status) ? () => toggleStatus(status) : undefined
              }
            >
              {STATUS_META[status].label}
            </JxChip>
          ))}
        </div>
      </div>

      {filteredProjects.length === 0 ? (
        <JxEmptyState
          title="Нет проектов по выбранным фильтрам"
          description="Снимите фильтр статуса или сбросьте все, чтобы увидеть полный список."
        >
          <JxButton variant="primary" onClick={resetFilters}>
            Сбросить фильтры
          </JxButton>
        </JxEmptyState>
      ) : (
        <>
          <div
            className="jx-stack"
            style={{ gap: 'var(--jx-space-3)' }}
          >
            {pageProjects.map((project) => (
              <div
                key={project.id}
                className="jx-card"
                style={{
                  display: 'flex',
                  alignItems: 'center',
                  justifyContent: 'space-between',
                  gap: 'var(--jx-space-4)',
                  padding: 'var(--jx-space-4)',
                }}
              >
                <span className="jx-text-body" style={{ flex: 1 }}>
                  {project.name}
                </span>

                <JxProgressCircle
                  value={project.quotaPercent}
                  max={100}
                  size="sm"
                  showValue
                  aria-label={`Квота использована на ${project.quotaPercent}%`}
                />

                <JxBadge variant={STATUS_META[project.status].badgeVariant}>
                  {STATUS_META[project.status].label}
                </JxBadge>
              </div>
            ))}
          </div>

          {pageCount > 1 && (
            <JxPagination
              page={currentPage}
              pageCount={pageCount}
              onPageChange={setPage}
            />
          )}
        </>
      )}
    </div>
  );
}

